edits.newText:
pushEvent(type, extra = {}) {
  const ev = {
    ...extra,
    t: Math.round(performance.now() - startTime),
    type,
  };
  if (extra && extra.type && extra.type !== type) {
    ev.subType = extra.type;
  }
  window.__events.push(ev);
  if (window.__events.length > 250) window.__events.shift();
},
